preset.customCSS:
@import url("https://cdn.jsdelivr.net/gh/orioncactus/pretendard@v1.3.9/dist/web/variable/pretendardvariable-dynamic-subset.min.css");

/* 바깥 래퍼: 메시지 폭을 확보하고 가운데 정렬합니다. */
.risu-chat > div {
  padding: 0;
  margin: auto;
  display: flex;
  justify-content: center;
  align-items: center;
  width: 100%;
}
.risu-chat > div > div {
  width: 100%;
  margin: auto;
  display: flex;
  justify-content: center;
}

/* 글꼴과 크기: 본문 글자 크기는 --rtmsa-font-size로 바꿉니다. */
.rtmsa {
  --rtmsa-bg-fill: transparent;
  --rtmsa-blur: none;
  --rtmsa-bg-edge: none;
  --rtmsa-font-body: "Pretendard Variable", "Pretendard", "Noto Sans KR", -apple-system, "Malgun Gothic", sans-serif;
  --rtmsa-font-display: "Pretendard Variable", "Pretendard", "Noto Sans KR", -apple-system, "Malgun Gothic", sans-serif;
  --rtmsa-font-size: 15.5px;
  --rtmsa-line-height: 1.7;
  --rtmsa-para-gap: .7em;
  --rtmsa-dialog-weight: 600;
  --rtmsa-avatar: clamp(2.6rem, 6vw, 3.2rem);
}

/* 본문: RisuAI 기본 색·글꼴 변수에 테마 값을 연결합니다. */
.rtmsa {
  --risu-font-family: var(--rtmsa-font-body);
  --FontColorStandard: var(--rtmsa-ink);
  --FontColorBold: var(--rtmsa-ink);
  --FontColorItalic: var(--rtmsa-muted);
  --FontColorItalicBold: var(--rtmsa-muted);
  --FontColorQuote1: var(--rtmsa-muted);
  --FontColorQuote2: var(--rtmsa-dialog);
  position: relative;
  isolation: isolate;
  width: 100%;
  min-width: 0;
  color: var(--rtmsa-ink);
  font-family: var(--rtmsa-font-body);
  font-size: var(--rtmsa-font-size);
  line-height: var(--rtmsa-line-height);
}
.rtmsa, .rtmsa *, .rtmsa *::before, .rtmsa *::after { box-sizing: border-box; }
/* 바깥 래퍼 보정(.risu-chat > div > div)이 테마 루트를 flex로 바꾸지 않게 루트 배치를 고정합니다. */
.rtmsa.rtmsa { display: block; }
.rtmsa__content {
  min-width: 0;
  color: var(--rtmsa-ink);
  word-break: keep-all;
  overflow-wrap: anywhere;
}
.rtmsa__content .chattext {
  --tw-prose-code: var(--rtmsa-ink);
  --tw-prose-pre-code: var(--rtmsa-ink);
  --tw-prose-pre-bg: var(--rtmsa-tint);
  max-width: none;
  color: var(--rtmsa-ink);
  font-size: var(--rtmsa-font-size) !important;
  line-height: var(--rtmsa-line-height) !important;
}
.rtmsa__content :is(p, li, td, th, blockquote) {
  font-size: var(--rtmsa-font-size);
  line-height: var(--rtmsa-line-height);
}
.rtmsa__content p { margin: 0 0 var(--rtmsa-para-gap); }
.rtmsa__content p:last-child { margin-bottom: 0; }
.rtmsa__content :is(h1, h2, h3, h4, h5, h6) {
  --risu-font-family: var(--rtmsa-font-display);
  margin: 1.3em 0 .55em;
  color: var(--rtmsa-ink);
  font-family: var(--rtmsa-font-display);
  line-height: 1.4;
  font-weight: 700;
}
.rtmsa__content h1 { font-size: calc(var(--rtmsa-font-size) * 1.6); }
.rtmsa__content h2 { font-size: calc(var(--rtmsa-font-size) * 1.35); }
.rtmsa__content h3 { font-size: calc(var(--rtmsa-font-size) * 1.15); }
.rtmsa__content :is(h4, h5, h6) { font-size: var(--rtmsa-font-size); }
.rtmsa__content strong { font-weight: 700; }
.rtmsa__content em { color: var(--rtmsa-muted); }
.rtmsa__content mark[risu-mark="quote1"],
.rtmsa__content mark[risu-mark="blockquote1"] { color: var(--rtmsa-muted); background: transparent; }
.rtmsa__content mark[risu-mark="quote2"],
.rtmsa__content mark[risu-mark="blockquote2"] {
  color: var(--rtmsa-dialog);
  font-weight: var(--rtmsa-dialog-weight);
  background: transparent;
}
.rtmsa__content blockquote {
  margin: 1em 0;
  padding: .3em 1em;
  border-left: 3px solid var(--rtmsa-line);
  color: var(--rtmsa-muted);
}
.rtmsa__content :is(ul, ol) { margin: 1em 0; padding-left: 1.5em; }
.rtmsa__content li { margin: .25em 0; color: var(--rtmsa-ink); }
.rtmsa__content li::marker { color: var(--rtmsa-muted); }
.rtmsa__content a { color: var(--rtmsa-accent); text-decoration: underline; }
.rtmsa__content hr { border: 0; border-top: 1px solid var(--rtmsa-line); margin: 1.5em 0; }
.rtmsa__content code {
  --risu-font-family: "IBM Plex Mono", ui-monospace, Consolas, monospace;
  padding: .1em .3em;
  border-radius: .2em;
  color: var(--rtmsa-ink);
  background: var(--rtmsa-tint);
  font-family: "IBM Plex Mono", ui-monospace, Consolas, monospace;
  font-size: calc(var(--rtmsa-font-size) * .88);
}
.rtmsa__content pre {
  max-width: 100%;
  overflow-x: auto;
  padding: .9em 1em;
  color: var(--rtmsa-ink);
  background: var(--rtmsa-tint);
  border-radius: .35rem;
  font-size: calc(var(--rtmsa-font-size) * .88);
  line-height: 1.5;
}
.rtmsa__content pre code { padding: 0; background: transparent; color: inherit; white-space: pre; overflow-wrap: normal; }
.rtmsa__content table {
  display: block;
  width: 100%;
  max-width: 100%;
  overflow-x: auto;
  border-collapse: collapse;
  margin: 1em 0;
}
.rtmsa__content :is(th, td) {
  padding: .5em .7em;
  color: var(--rtmsa-ink);
  border-bottom: 1px solid var(--rtmsa-line);
  text-align: left;
  vertical-align: top;
}
.rtmsa__content th { font-weight: 700; }
.rtmsa__content img { display: block; max-width: 100%; height: auto; margin: .75em auto; }
.rtmsa__content textarea.message-edit-area {
  width: 100%;
  max-width: 100%;
  min-width: 0;
  color: var(--rtmsa-ink) !important;
  background: var(--rtmsa-edit-bg) !important;
  border: 1px solid var(--rtmsa-line);
  border-radius: .4rem;
  font: inherit;
  font-size: var(--rtmsa-font-size) !important;
  line-height: var(--rtmsa-line-height) !important;
}

/* 조작부: 생성 정보와 버튼 */
.rtmsa__footer {
  --risu-theme-textcolor2: var(--rtmsa-muted);
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: .4rem .75rem;
  min-width: 0;
}
.rtmsa__info, .rtmsa__actions { min-width: 0; max-width: 100%; }
.rtmsa__info > div, .rtmsa__actions > div { flex-wrap: wrap; min-width: 0; gap: .3rem; }
.rtmsa__actions > div > div { flex-wrap: wrap; min-width: 0; }
.rtmsa__footer button {
  background: transparent;
  min-height: 1.9rem;
  padding: .25rem .4rem;
  border-radius: .3rem;
  white-space: normal;
}
.rtmsa__footer button:hover { background: var(--rtmsa-tint); }
.rtmsa :is(a, button, textarea):focus-visible { outline: 2px solid var(--rtmsa-accent); outline-offset: 2px; }

/* 아바타 틀: RisuAI가 넣는 배경 이미지 칸을 틀에 맞춥니다. */
.rtmsa__portrait { overflow: hidden; background: var(--rtmsa-tint); }
.rtmsa__portrait > * {
  width: 100% !important;
  height: 100% !important;
  min-width: 0 !important;
  min-height: 0 !important;
  background-size: cover !important;
  background-position: center 22% !important;
  border: 0 !important;
  border-radius: inherit !important;
}

.rtmsa__bg {
  position: absolute;
  inset: 0;
  z-index: -1;
  pointer-events: none;
  border-radius: inherit;
  background: var(--rtmsa-bg-fill);
  -webkit-backdrop-filter: var(--rtmsa-blur);
  backdrop-filter: var(--rtmsa-blur);
  box-shadow: var(--rtmsa-bg-edge);
}

/* 구조: 메신저 한쪽 */

.rtmsa { background: var(--rtmsa-wall); padding: .45rem clamp(.75rem, 3vw, 1.5rem); }
.rtmsa__row { display: flex; align-items: flex-start; gap: .6rem; max-width: 52rem; margin: 0 auto; }
/* 두 사람 모두 같은 크기의 원형 초상 */
.rtmsa__avatar { flex: 0 0 auto; width: var(--rtmsa-avatar); aspect-ratio: 1; }
.rtmsa__portrait { width: 100%; height: 100%; border-radius: 50%; background: var(--rtmsa-tint); box-shadow: 0 0 0 1px var(--rtmsa-frame); }
.rtmsa__main { flex: 1 1 auto; min-width: 0; display: flex; flex-direction: column; align-items: flex-start; }
.rtmsa__name { margin: .1rem .2rem .3rem; color: var(--rtmsa-muted); font-size: .8em; font-weight: 600; }
.rtmsa__bubble {
  max-width: min(100%, 34em);
  padding: .65em .95em;
  background: var(--rtmsa-panel);
  border: 1px solid var(--rtmsa-line);
  border-radius: 1.05rem;
  border-top-left-radius: .3rem;
  box-shadow: 0 2px 6px var(--rtmsa-shadow);
}
.rtmsa__footer { margin: .25rem .2rem 0; font-size: .82em; }
/* 사용자: 오른쪽 */
.rtmsa--user .rtmsa__row { flex-direction: row-reverse; }
.rtmsa--user .rtmsa__main { align-items: flex-end; }
.rtmsa--user .rtmsa__bubble { background: var(--rtmsa-panel-user); border-radius: 1.05rem; border-top-right-radius: .3rem; }
.rtmsa--user .rtmsa__footer { justify-content: flex-end; }
@media (max-width: 560px) { .rtmsa__bubble { max-width: 100%; } }

/* ── 배색과 소재: 이 블록만 바꾸면 같은 분류의 다른 변주가 됩니다. (갈색) ── */
.rtmsa {
  --rtmsa-wall: #2a231f;
  --rtmsa-panel: #352c26;
  --rtmsa-panel-user: #3d332c;
  --rtmsa-ink: #ece3d8;
  --rtmsa-muted: #b0a190;
  --rtmsa-accent: #c9a77c;
  --rtmsa-dialog: #e6c9a0;
  --rtmsa-frame: #4b3f36;
  --rtmsa-shadow: rgba(0, 0, 0, .3);
  --rtmsa-line: #4a3d34;
  --rtmsa-tint: #40352e;
  --rtmsa-edit-bg: #2f2722;
}
